{
  "PROP-56ad1eb2-inv-014": {
    "property_id": "PROP-56ad1eb2-inv-014",
    "audit_result": {
      "property_id": "PROP-56ad1eb2-inv-014",
      "classification": "vulnerability",
      "code_path": "consensus/types/src/chain_spec.rs::BlobSchedule::new::L1530-1537",
      "proof_trace": "BlobSchedule deserialization and construction lack validation that max_blobs_per_block <= MAX_BLOB_COMMITMENTS_PER_BLOCK (4096). Config entries can specify arbitrary values (e.g., 5000) which are accepted without bounds checking, creating type-safety violations and potential consensus splits.",
      "attack_scenario": "Attacker provides ChainSpec config with BLOB_SCHEDULE entry containing max_blobs_per_block=5000. Nodes load config successfully, then accept blocks with 4500 blob commitments (passing runtime check at block_verification.rs:885) but violating SSZ VariableList constraints, causing divergent validation behavior.",
      "checklist_id": "PROP-56ad1eb2-inv-014"
    },
    "text": "All BLOB_SCHEDULE max_blobs_per_block values must be <= MAX_BLOB_COMMITMENTS_PER_BLOCK.",
    "assertion": "forall entry in BLOB_SCHEDULE: entry.max_blobs_per_block <= MAX_BLOB_COMMITMENTS_PER_BLOCK",
    "covers": "SG-001",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

